#[path = "../src/pricing.rs"] mod pricing;
#[path = "../src/discount.rs"] mod discount;
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let a: u32 = args[2].parse().unwrap();
    let b: u32 = args[3].parse().unwrap();
    let result = match args[1].as_str() {
        "subtotal" => pricing::subtotal(a, b),
        "discount" => discount::discounted_total(a, b),
        _ => panic!("unadmitted check"),
    };
    println!("{result}");
}
